require_once __DIR__.'/config.php'; if(!is_admin()) { flash('error','หน้านี้สำหรับผู้ดูแลระบบ'); redirect('login.php'); }
if($_SERVER['REQUEST_METHOD']==='POST'){ if(!verify_csrf($_POST['csrf']??null)){http_response_code(403);exit('คำขอไม่ถูกต้อง');} $status=$_POST['status']??'pending'; if(in_array($status,['pending','paid','packing','shipped','completed','cancelled'],true)){db()->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);flash('success','อัปเดตสถานะคำสั่งซื้อแล้ว');} redirect('admin_orders.php');}
$orders=db()->query('SELECT o.*,u.name,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC')->fetchAll(); $page_title='จัดการคำสั่งซื้อ | '.STORE_NAME; require __DIR__.'/partials_header.php';
?><main class="container"><section class="panel"><div class="eyebrow">ORDER MANAGEMENT</div><h1>จัดการคำสั่งซื้อ</h1><div class="table-wrap"><table><tr><th>เลขที่</th><th>ลูกค้า</th><th>ยอดรวม</th><th>วันที่</th><th>สถานะ</th><th></th></tr><?php foreach($orders as $o): ?><tr><td><b>#<?=e($o['order_number'])?></b><br><small><?=e($o['shipping_name'])?></small></td><td><?=e($o['name'])?><br><small class="muted"><?=e($o['email'])?></small></td><td>฿<?=number_format($o['total'],2)?></td><td><?=e(date('d/m/Y H:i',strtotime($o['created_at'])))?></td><td><?=e($o['status'])?></td><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['pending'=>'รอดำเนินการ','paid'=>'ชำระเงินแล้ว','packing'=>'กำลังแพ็ก','shipped'=>'จัดส่งแล้ว','completed'=>'สำเร็จ','cancelled'=>'ยกเลิก'] as $v=>$label): ?><option value="<?=$v?>" <?=$o['status']===$v?'selected':''?>><?=$label?></option><?php endforeach; ?></select><button class="button button-small">บันทึก</button></form></td></tr><?php endforeach; ?></table><?php if(!$orders): ?><p class="muted">ยังไม่มีคำสั่งซื้อ</p><?php endif; ?></div></section></main><?php require __DIR__.'/partials_footer.php'; ?>
